import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { meApi } from '../api/me';
import { RefundEligibility } from '../types';
import { useShop } from '../context/ShopContext';
import {
  RotateCcw,
  ShieldAlert,
  CheckCircle2,
  AlertCircle,
  ArrowLeft,
  Loader2,
  Info,
  Clock,
} from 'lucide-react';

export const RefundRequest: React.FC = () => {
  const { orderId } = useParams<{ orderId: string }>();
  const { formatPrice, currency } = useShop();
  const navigate = useNavigate();

  const [eligibility, setEligibility] = useState<RefundEligibility | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [amountInput, setAmountInput] = useState<string>('');
  const [reason, setReason] = useState<string>('');
  const [notes, setNotes] = useState<string>('');
  const [submitting, setSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState<any | null>(null);

  useEffect(() => {
    if (!orderId) return;

    const checkEligibility = async () => {
      setLoading(true);
      setError(null);
      try {
        const data = await meApi.getRefundEligibility(orderId);
        setEligibility(data);
        if (data.allowedAmount) {
          setAmountInput(String(data.allowedAmount));
        }
      } catch (err: any) {
        setError(err?.error || err?.message || 'Could not verify refund eligibility for this order.');
      } finally {
        setLoading(false);
      }
    };

    checkEligibility();
  }, [orderId]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!orderId) return;

    setSubmitting(true);
    setError(null);

    const idempotencyKey = `ref-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
    const parsedAmount = amountInput ? Math.round(Number(amountInput)) : undefined;

    try {
      const res = await meApi.requestRefund(orderId, idempotencyKey, {
        amount: parsedAmount,
        reason: reason.trim() || undefined,
        notes: notes.trim() || undefined,
      });

      setSubmitSuccess(res.refund);
    } catch (err: any) {
      setError(
        err?.error ||
          err?.message ||
          'Failed to submit refund request. Verify remaining refundable balance and try again.'
      );
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="max-w-xl mx-auto px-4 py-24 text-center">
        <Loader2 size={32} className="animate-spin text-purple-500 mx-auto mb-3" />
        <p className="text-xs font-mono text-slate-500">Checking refund policy eligibility...</p>
      </div>
    );
  }

  if (submitSuccess) {
    return (
      <div className="max-w-xl mx-auto px-4 py-16">
        <div className="p-8 rounded-3xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm text-center space-y-5">
          <div className="w-14 h-14 rounded-2xl bg-emerald-500/10 text-emerald-500 flex items-center justify-center mx-auto">
            <CheckCircle2 size={30} />
          </div>

          <div>
            <h1 className="font-display text-xl font-bold text-slate-900 dark:text-white">
              Refund Request Submitted
            </h1>
            <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
              Your request has been placed in status{' '}
              <span className="font-mono font-bold text-purple-600 dark:text-purple-400">REQUESTED</span>{' '}
              and assigned to finance operations for review.
            </p>
          </div>

          <div className="p-4 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs font-mono text-left space-y-1.5">
            <div className="flex justify-between">
              <span className="text-slate-400">Refund ID:</span>
              <span className="text-slate-900 dark:text-white font-bold">{submitSuccess.refundId}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Order ID:</span>
              <span className="text-slate-900 dark:text-white font-bold">{submitSuccess.orderId}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-400">Amount Requested:</span>
              <span className="text-emerald-600 dark:text-emerald-400 font-bold">
                {formatPrice(submitSuccess.requestedAmount || submitSuccess.amount, submitSuccess.currency)}
              </span>
            </div>
          </div>

          <div className="pt-2 flex flex-col sm:flex-row items-center justify-center gap-3">
            <Link
              to="/refunds"
              className="w-full sm:w-auto px-5 py-2.5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl text-xs font-semibold"
            >
              View Refund History
            </Link>
            <Link
              to={`/orders/${orderId}`}
              className="w-full sm:w-auto px-5 py-2.5 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl text-xs font-semibold"
            >
              Return to Order
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const isEligible = eligibility?.eligible;

  return (
    <div className="max-w-2xl mx-auto px-4 py-12">
      <Link
        to={`/orders/${orderId}`}
        className="inline-flex items-center gap-1.5 text-xs font-semibold text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors mb-6"
      >
        <ArrowLeft size={13} />
        <span>Back to Order #{orderId}</span>
      </Link>

      <div className="p-8 rounded-3xl bg-white dark:bg-[#101216] border border-slate-200 dark:border-slate-800 shadow-sm space-y-6">
        <div>
          <div className="flex items-center gap-2">
            <RotateCcw size={16} className="text-purple-500" />
            <span className="text-[11px] font-mono uppercase font-bold text-purple-600 dark:text-purple-400 tracking-wider">
              FINANCIAL RESOLUTION
            </span>
          </div>
          <h1 className="font-display text-2xl font-bold text-slate-900 dark:text-white mt-1">
            Request Order Refund
          </h1>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
            Submit a formal refund claim against order #{orderId}. Subject to policy terms and remaining refundable balance.
          </p>
        </div>

        {error && (
          <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-500 text-xs flex items-start gap-2.5">
            <AlertCircle size={16} className="shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {!isEligible ? (
          <div className="p-6 rounded-2xl bg-amber-500/10 border border-amber-500/30 space-y-3">
            <div className="flex items-center gap-2 text-amber-600 dark:text-amber-400 font-semibold text-xs">
              <ShieldAlert size={16} />
              <span>Refund Ineligible</span>
            </div>
            <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed">
              {eligibility?.reason
                ? `Reason: ${eligibility.reason.replace(/_/g, ' ')}`
                : 'This order is not eligible for refund under current policy constraints or window.'}
            </p>
            {eligibility?.expiresAt && (
              <div className="text-[11px] font-mono text-slate-500 flex items-center gap-1">
                <Clock size={12} />
                <span>Refund window expired at: {new Date(eligibility.expiresAt).toLocaleString()}</span>
              </div>
            )}
            <div className="pt-2">
              <Link
                to={`/orders/${orderId}`}
                className="text-xs font-semibold text-amber-600 dark:text-amber-400 hover:underline"
              >
                Return to order details
              </Link>
            </div>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-5">
            {/* Eligibility summary */}
            <div className="p-4 rounded-xl bg-purple-500/10 border border-purple-500/20 text-xs font-mono space-y-1.5">
              <div className="flex justify-between">
                <span className="text-slate-500">Maximum Allowed Amount:</span>
                <span className="text-purple-600 dark:text-purple-400 font-bold">
                  {formatPrice(eligibility.allowedAmount)}
                </span>
              </div>
              {eligibility.expiresAt && (
                <div className="flex justify-between text-[11px] text-slate-400">
                  <span>Policy Window Closes:</span>
                  <span>{new Date(eligibility.expiresAt).toLocaleDateString()}</span>
                </div>
              )}
            </div>

            {/* Amount input */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Refund Amount ({currency})
              </label>
              <input
                type="number"
                min="1"
                max={eligibility.allowedAmount}
                value={amountInput}
                onChange={e => setAmountInput(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs font-mono text-slate-900 dark:text-white focus:outline-none focus:border-purple-500"
                placeholder={String(eligibility.allowedAmount)}
              />
              <span className="text-[11px] text-slate-400 mt-1 block">
                Leave default to request full remaining eligible balance.
              </span>
            </div>

            {/* Reason */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Reason for Refund (up to 500 chars)
              </label>
              <input
                type="text"
                maxLength={500}
                required
                value={reason}
                onChange={e => setReason(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white focus:outline-none focus:border-purple-500"
                placeholder="E.g., Incompatible execution environment or accidental duplicate order"
              />
            </div>

            {/* Notes */}
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">
                Additional Notes for Finance Staff (Optional, up to 2000 chars)
              </label>
              <textarea
                rows={3}
                maxLength={2000}
                value={notes}
                onChange={e => setNotes(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-xs text-slate-900 dark:text-white focus:outline-none focus:border-purple-500 resize-none"
                placeholder="Provide any additional transaction context..."
              />
            </div>

            <div className="p-4 rounded-xl bg-slate-50 dark:bg-slate-900/60 border border-slate-200 dark:border-slate-800 text-xs text-slate-500 space-y-1">
              <div className="flex items-center gap-1 font-semibold text-slate-700 dark:text-slate-300">
                <Info size={13} className="text-purple-500" />
                <span>Notice on Digital Access</span>
              </div>
              <p className="text-[11px] leading-relaxed">
                If the refund is approved and processed, associated digital repository and course licenses will be updated accordingly in your workspace library.
              </p>
            </div>

            <button
              type="submit"
              disabled={submitting || !reason.trim()}
              className="w-full py-3.5 px-4 rounded-xl bg-purple-600 hover:bg-purple-500 text-white font-semibold text-xs inline-flex items-center justify-center gap-2 transition-all disabled:opacity-50 cursor-pointer"
            >
              {submitting ? (
                <>
                  <Loader2 size={14} className="animate-spin" />
                  <span>Submitting Request...</span>
                </>
              ) : (
                <>
                  <RotateCcw size={14} />
                  <span>Submit Formal Refund Request</span>
                </>
              )}
            </button>
          </form>
        )}
      </div>
    </div>
  );
};

export default RefundRequest;
